import { CONCISE_PBQ_REVIEW } from "./sy0701ConciseExplanations.js";
import { SECOND_PASS_PBQ_REVIEW } from "./sy0701SecondPassReview.js";
// Authored, evidence-based corrections. Coverage is checked separately from UI
// normalisation; generated fallback text does not count as an editorial review.
import { PUBLISHED_PBQ_REVIEW } from "./sy0701PublishedReview.js";

export const PBQ_REVIEW = {
  p099: { ch:"4", objective:"4.8", cat:"Incident Response", scenario:"An approved playbook for a currently reported email directs initial safe analysis, mailbox quarantine, blocking of confirmed malicious destinations, recipient-impact investigation, then a campaign-summary notice. Urgent safety warnings, coordination and victim containment may happen at any time. Order the work packages in this specific playbook.", explanation:"The order follows the supplied playbook, not a universal instruction to delay warnings. Quarantine and blocking reduce further exposure, while logs and recipient follow-up establish impact. A web request alone does not prove credentials were entered. Use safe analysis tooling and respond promptly to confirmed compromise; don't wait for a final campaign notice.", itemNotes:{o0:"Quarantine identified campaign messages under the approved procedure to reduce further interaction.",o1:"Initial safe analysis establishes the indicators needed for the specified containment actions.",o2:"The final campaign-summary notice follows the investigation here; urgent warnings need not wait.",o3:"Correlate access logs and other evidence and contact recipients as appropriate; a click is not proof of credential submission.",o4:"Block confirmed malicious destinations with attention to shared infrastructure and unintended business impact."}},
  p211: { difficulty:"medium", choices:["Portal: warm site requiring a day to activate; database: daily backup; logs: standard writable storage", "Portal: tested hot-site failover; database: tested recovery points no more than 15 minutes apart; logs: enforced WORM retention", "Portal: tested hot-site failover; database: daily backup; logs: enforced WORM retention", "Portal: tested hot-site failover; database: tested 15-minute recovery points; logs: administrator-editable file share"], explanation:"The chosen controls must be tested against the actual recovery time and data-loss targets. A hot site does not guarantee a minute-level RTO without tested failover and dependencies. Backups or replication must actually achieve the 15-minute RPO. Retention must be enforced against the relevant administrator actions; a label saying 'immutable' alone is insufficient.", wrongFeedback:{0:"A day-long activation and daily-only recovery points miss the specified minute-level recovery and 15-minute data-loss requirements.",2:"Daily backups alone can lose far more than the permitted 15 minutes of data.",3:"An administrator-editable share does not meet the requirement to prevent early alteration or deletion."}},
  p082: { objective:"3.2", title:"Choose secure remote-access concepts", blanks:[{id:"b0",sentence:"A ___ protects traffic between a remote device and an organisation's gateway over an untrusted network.",answer:"VPN",hint:"VPN, VLAN, NAT, DNS"},{id:"b1",sentence:"An ___ VPN uses the IP-layer security suite to protect selected network traffic.",answer:"IPsec",hint:"IPsec, HTTP, SMTP, FTP"},{id:"b2",sentence:"A ___ configuration sends only selected destinations through the VPN while other traffic uses the local connection.",answer:"split-tunnel",hint:"full-tunnel, split-tunnel, site-to-site"}], explanation:"A VPN protects a defined traffic path under its configuration and key-management assumptions; it does not make a compromised endpoint safe. IPsec provides IP-layer protection. Split tunnelling reduces traffic through the corporate gateway but requires controls for the direct internet path. Product code-line counts and blanket speed claims are not needed to assess these SY0-701 concepts.", blankNotes:{b0:"A virtual private network provides protected connectivity over an otherwise untrusted path.",b1:"IPsec is the IP-layer security suite; the listed application protocols are not VPN security suites.",b2:"Split tunnelling routes selected destinations through the tunnel; full tunnelling routes the configured general traffic through it."}},
  p083: { objective:"4.9", explanation:"Correlate sources because each provides a different view and can have coverage gaps. Process events require suitable auditing; DNS requests do not prove successful application connections; an encrypted proxy session may not expose the full URL. A cloud identity is not necessarily the human actor, and endpoint capabilities vary.", itemNotes:{i0:"Enabled authentication and process-creation auditing can link logons and launched processes on the host.",i1:"DNS logs show observed name-resolution requests, useful for investigating unusual destinations.",i2:"A web gateway records web requests to the extent visible through its supported inspection and logging.",i3:"Cloud audit events record supported resource/API actions and the identities used.",i4:"EDR supplies configured endpoint behaviour such as process relationships and file or memory activity."}},
  p084: { objective:"4.8", title:"Collect and correlate volatile evidence", scenario:"An authorised incident responder needs a live host's process command lines and network connections. The incident commander has assessed safety and containment needs and approved collection using trusted tooling to an evidence destination.", question:"Which collection plan best meets the stated evidence need?", answer:"Required evidence: process IDs and command lines; current network endpoints and owning process IDs.\nRecord source, acquisition times and tool versions.\nCollections occur at different instants, so account for process termination and PID reuse.", choices:["Capture process details and connections with trusted tools, retain timestamps and correlate owning process IDs", "List installed files only and infer which programs are running", "Power off the host before collecting its live process and connection state", "Archive the system drive and assume it includes the current contents of RAM"], explanation:"Collect the required volatile sources and document their acquisition context; two sequential commands are not an atomic simultaneous snapshot. On Windows, process command lines can be obtained from Win32_Process via CIM rather than assuming Get-Process exposes a CommandLine property. Follow the incident's safety and containment decision; collection-before-isolation is not a universal rule.", wrongFeedback:{1:"Installed files do not establish which processes are running or their active connections.",2:"Powering off destroys much volatile state; it does not satisfy the approved live-collection task.",3:"A disk archive does not automatically contain the current process state or full RAM."}},
  p085: { objective:"4.9", difficulty:"medium", title:"Choose evidence sources for an endpoint investigation", items:[{id:"i0",label:"Recent-document shortcut artefacts"},{id:"i1",label:"Configured user-logon startup entries"},{id:"i2",label:"Application execution artefacts"},{id:"i3",label:"Recorded removable-storage device history"},{id:"i4",label:"Retained recycle-bin metadata and content"}], targets:[{id:"t0",label:"Clues about previously referenced documents and paths"},{id:"t1",label:"Programs configured to start when the user signs in"},{id:"t2",label:"Clues supporting a program execution timeline"},{id:"t3",label:"Identifiers of some previously attached storage devices"},{id:"t4",label:"Original paths, deletion metadata and possibly recoverable deleted content"}], explanation:"These artefacts support an investigation but require corroboration. Retention, feature configuration, OS version and tampering affect availability. A prefetch file is evidence to interpret, not absolute proof of every execution detail; device history is not a complete list of every device ever attached. This exercise tests source selection rather than registry-path memorisation.", itemNotes:{i0:"Shortcut metadata can preserve referenced paths and related timestamps, but does not prove a particular human read the contents.",i1:"Startup entries reveal configured persistence opportunities; a listed entry need not have executed successfully.",i2:"Execution artefacts help build timelines and should be correlated with logs and other evidence.",i3:"Device history can link identifiers to observed storage attachments but has coverage and retention limitations.",i4:"Recycle-bin evidence can retain deletion metadata and content until removed or overwritten; recovery is not guaranteed."}},
  p086: { objective:"4.3", scenario:"The emergency procedure calls for initial affected-asset identification, approved temporary exposure reduction, compatibility testing, confirmation of the deployment plan with stakeholders, and deployment followed by validation. Order these five work packages according to that procedure. Safety and incident communication continue throughout.", items:[{id:"o0",label:"Deploy the approved patch and validate remediation and service health"},{id:"o1",label:"Identify affected systems and their exposure"},{id:"o2",label:"Test patch compatibility and rollback in the available staging environment"},{id:"o3",label:"Apply and verify approved temporary restrictions or disable the vulnerable feature"},{id:"o4",label:"Confirm the deployment window, approval and rollback plan with stakeholders"}], explanation:"Follow the supplied emergency procedure while communicating continuously. Temporary controls reduce exposure but are not guaranteed to stop every exploit. For an actively compromised system, incident response and urgent isolation may proceed alongside patch work. Verification and removal/review of temporary controls are necessary follow-up activities.", itemNotes:{o0:"Deployment is followed by security and operational verification, not an assumption that installation equals remediation.",o1:"Identify the affected population and exposure to direct an appropriate response.",o2:"Test the change and rollback to reduce avoidable outage risk.",o3:"Temporary restrictions reduce exposure while the permanent fix is prepared; confirm they work.",o4:"Confirm authorisation, timing and rollback before this planned production change, without delaying earlier incident communication."}},
  p089: { choices:["Count login_failure events per source IP over a rolling five-minute window and alert when the count exceeds five", "Count login_failure events per username over five minutes and alert when the count exceeds five", "Count all login events per source IP over five minutes and alert when the count exceeds five", "Count login_failure events per source IP over five minutes and alert when the count reaches five"], explanation:"The stated rule needs failures only, grouping by source IP, a five-minute window and a strict greater-than-five threshold. A rolling window avoids fixed-bin boundary misses. Validate tuning exceptions and test detection coverage; a source address can represent many users behind NAT, and this rule alone misses distributed or low-and-slow attempts.", wrongFeedback:{1:"Grouping by username answers a different requirement and combines different source addresses.",2:"Including successful logins can trigger the rule without the required number of failures.",3:"Reaching five is not the requested threshold of more than five; the first qualifying count is six."}},
  p094: { objective:"4.4", title:"Tune a noisy authentication alert safely", question:"Which tuning change best reduces known test noise while preserving detection coverage?", currentConfig:"Investigation confirms an authorised test generates predictable authentication failures. The test has a named owner, defined source, approved accounts and a two-hour window. Similar activity outside these conditions remains suspicious.", choices:["Apply a documented, time-limited exception matching the approved test conditions and validate retained detection", "Exclude every service account from all authentication detections", "Permanently ignore every event from the test source IP", "Raise the threshold to 1,000 failures without testing the resulting detection gap"], correct:0, explanation:"A narrowly scoped, expiring exception can reduce verified test noise while retaining visibility elsewhere. Do not assume service accounts or scanner hosts cannot be compromised. Monitor excluded activity appropriately and test that genuine attacks still alert. There is no universal number of guesses within which an attack succeeds.", wrongFeedback:{1:"Service accounts can be attacked or misused; a blanket exclusion creates a broad blind spot.",2:"A permanent IP exclusion outlives the approved test and can hide later compromise or unrelated activity.",3:"An arbitrary high threshold trades noise for missed attacks without evidence that the tradeoff is acceptable."}},
  p095: { objective:"5.4", targets:[{id:"t0",label:"Protected health information within covered US healthcare relationships"},{id:"t1",label:"Payment-card account data and relevant payment environments"},{id:"t2",label:"Personal-data processing meeting the regulation's territorial scope"},{id:"t3",label:"Financial-reporting controls for covered public companies"},{id:"t4",label:"Education records at qualifying US educational institutions"}], explanation:"Applicability requires examining each regime's scope and exceptions. GDPR is not triggered solely by an individual's EU citizenship or residence in every situation; PCI DSS is an industry standard. A hospital handling a payment from an EU visitor does not automatically establish every claimed GDPR condition. Multiple regimes can apply, but verify rather than assume.", itemNotes:{i0:"HIPAA duties depend on covered-entity and business-associate scope and the information involved.",i1:"PCI DSS addresses cardholder-data security and relevant entities and environments, not every kind of financial information.",i2:"GDPR scope includes EU establishment and specified offering/monitoring conditions beyond the EU; citizenship alone is not the test.",i3:"SOX governs covered corporate financial reporting and controls; specific attestation requirements have scope and exemptions.",i4:"FERPA concerns student education records at educational agencies/institutions within its funding-linked scope."}},
  p096: { objective:"5.2", scenario:"The organisation's risk process identifies exposures, analyses likelihood and impact, selects an approved treatment, implements the decision, then monitors results and changes. Arrange the activities for this stated cycle.", explanation:"Risk assessment and treatment are iterative. Likelihood and impact can inform qualitative ratings or quantitative estimates; multiplying ordinal labels is not a universally valid numerical measure. This is a simplified process, not a verbatim sequence attributed to NIST SP 800-39, whose core framing differs.", itemNotes:{o0:"Monitoring checks treatment effectiveness and new conditions, feeding the next assessment.",o1:"Implement the approved treatment and assign ownership; acceptance and transfer need not mean deploying a technical control.",o2:"Identify assets, threats and vulnerabilities before analysing the stated risks.",o3:"Choose treatment in light of assessed exposure, tolerance, feasibility and authority.",o4:"Analyse likelihood and impact using an appropriate method and explicit assumptions."}},
  p069: { objective:"2.1", scenario:"Use the stated defining context in each example to identify the actor category. Motivations can overlap; these descriptions are examples rather than reliable attribution rules.", items:[{id:"i0",label:"An organised criminal enterprise runs fraud for profit"},{id:"i1",label:"A government-sponsored group collects strategic intelligence"},{id:"i2",label:"A protest group disrupts services to advance its ideology"},{id:"i3",label:"An employee deliberately misuses authorised access over a grievance"},{id:"i4",label:"An inexperienced attacker relies on ready-made tools for recognition"}], targets:[{id:"t0",label:"Organised crime"},{id:"t1",label:"Nation-state actor"},{id:"t2",label:"Hacktivist"},{id:"t3",label:"Malicious insider"},{id:"t4",label:"Unskilled attacker"}], explanation:"Classify from the supplied context, not tools alone. Nation-state sponsorship and persistent advanced activity are different concepts; APT is not a synonym for every government actor. Insiders can have many motivations, and using a public tool does not itself prove an attacker is unskilled.", itemNotes:{i0:"The stated organised profit-seeking enterprise fits organised crime.",i1:"Government sponsorship is the defining context for this nation-state example.",i2:"The stated protest and ideological goal fits hacktivism.",i3:"Deliberate misuse of legitimate insider access fits a malicious insider.",i4:"The explicitly stated low expertise, not merely a public tool name, supports the unskilled classification."}},
  p070: { ch:"4", objective:"4.5", cat:"Enterprise Security", title:"Restrict workstation remote administration", scenario:"A workstation must allow inbound TCP 3389 only from 10.10.0.0/24 and deny other unsolicited inbound traffic. Outbound traffic remains allowed. Choose the effective policy that meets these requirements; assume no other overlapping allow or block rules.", question:"Which proposed policy meets all the stated requirements?", currentConfig:"Required management sources: 10.10.0.0/24\nRequired service: TCP 3389\nOther unsolicited inbound traffic: deny\nOutbound: allow", choices:["Allow inbound TCP 3389 from 10.10.0.0/24; use default inbound deny and outbound allow", "Allow inbound TCP 3389 from any source; use default inbound deny and outbound allow", "Allow all inbound ports from 10.10.0.0/24; use default inbound deny and outbound allow", "Allow TCP 3389 from 10.10.0.0/24 and all inbound traffic from the domain-controller subnet"], correct:0, explanation:"The first policy limits both source and service and uses a default deny for other unsolicited inbound traffic. Default deny is not the same as an explicit broad block rule that could override exceptions in a particular firewall. An any-source host rule permits any reachable source; it does not alone prove internet reachability through upstream controls.", wrongFeedback:{1:"Any-source RDP violates the specified management-subnet restriction.",2:"Allowing all ports from the management subnet exceeds the single required service.",3:"The extra domain-controller subnet exception permits unspecified inbound traffic contrary to the requirements."}},
  p073: { objective:"3.2", items:[{id:"i0",label:"Internet-facing boundary"},{id:"i1",label:"DMZ / screened subnet"},{id:"i2",label:"Internal corporate segment"},{id:"i3",label:"Dedicated out-of-band management network"},{id:"i4",label:"Visitor guest network"}], targets:[{id:"t0",label:"External connection boundary controlled by ingress and egress policy"},{id:"t1",label:"Public-service segment with filtered paths to other zones"},{id:"t2",label:"Corporate assets requiring internal access controls and segmentation"},{id:"t3",label:"Restricted administration path separate from production data traffic"},{id:"t4",label:"Visitor access isolated from corporate resources under this site's policy"}], explanation:"Location in an internal segment does not make a user or device automatically trustworthy. A DMZ can have narrowly authorised connections to internal services; an absolute ban is not its definition. A true out-of-band management path is separate from the production path, and guest/partner entitlements depend on policy.", itemNotes:{i0:"The external boundary applies policy to traffic crossing to and from outside networks.",i1:"A screened subnet isolates exposed services while permitting specifically authorised flows.",i2:"Internal assets still require verification, least privilege and appropriate segmentation.",i3:"Out-of-band management provides a separate administration path with tightly limited access.",i4:"This example's visitor network offers connectivity without granting corporate-resource access."}},
  p074: { choices:["Block anonymous object reads and retain least-privilege application and administration access", "Keep public reads but rotate the storage encryption key", "Keep public reads because listing is disabled", "Keep public reads and rely on access-log alerts for confidentiality"], wrongFeedback:{1:"Server-side encryption ordinarily decrypts for permitted reads; key rotation does not revoke an overly public policy.",2:"An attacker can request a known or guessed object name without permission to list the container.",3:"Logs can detect exposure after it occurs but do not stop unauthorised readers receiving the objects."}},
  p075: { ch:"4", objective:"4.3", cat:"Vulnerability Management", scenario:"This team's release workflow defines requirements and threat models first, runs static checks during development, requires peer review before merge, tests the running build, then performs its final authorised penetration test. Order these activities according to that workflow.", explanation:"Early security feedback helps detect issues before release. Static analysis does not always require an uncompiled program: tools may analyse source, bytecode or binaries. Reviews and tests can recur throughout development; this supplied workflow is not a universal ordering or a guaranteed 1-to-100 cost ratio.", itemNotes:{o0:"The final authorised penetration test follows the running-build checks in this team's workflow.",o1:"Requirements and threat modelling identify security needs before implementation.",o2:"Static analysis examines code-related artefacts without exercising the application as a running black-box target.",o3:"Dynamic analysis exercises the running build and therefore follows availability of that build here.",o4:"Peer review checks the proposed changes before this workflow permits a merge."}},
  p077: { objective:"3.1", blanks:[{id:"b0",sentence:"In the stated IaaS contract, the customer manages ___ while the provider manages physical hardware and the hypervisor.",answer:"guest OS patching and hardening",hint:"physical datacenter security, hypervisor updates, guest OS patching and hardening, network backbone availability"},{id:"b1",sentence:"In the stated SaaS contract, the provider manages ___ while the customer configures tenant access, protects its data and manages its endpoints.",answer:"application security and OS maintenance",hint:"user data classification, identity federation setup, application security and OS maintenance, customer endpoint patching"},{id:"b2",sentence:"A ___ can apply cloud-use policies and visibility through supported proxy or API integrations.",answer:"CASB",hint:"WAF, SIEM, CASB, IDS"}], explanation:"Cloud responsibilities depend on service and contract. SaaS customers retain tenant configuration, identities, data governance, endpoints and other duties; the provider does not own every remaining security obligation. A CASB offers cloud-use visibility and controls through supported integrations and is not universally mandatory or always inline.", blankNotes:{b0:"A typical IaaS customer maintains its guest OS; the supplied contract assigns the lower infrastructure to the provider.",b1:"The SaaS provider operates and maintains the supplied application stack; customer-controlled settings and usage remain customer responsibilities.",b2:"A cloud access security broker applies supported cloud-use policies; a SIEM primarily aggregates and analyses events."}},
  p078: { objective:"3.2", scenario:"The approved three-tier design permits internet-to-web HTTPS, web-to-application TCP 8080 and application-to-database TCP 3306. It forbids direct internet access to the application/database tiers and direct web-to-database access. Assume stateful return traffic is handled separately and unlisted new connections are denied.", question:"Which sequence of actions correctly completes rules 1–5?", choices:["Permit, deny, permit, permit, deny", "Permit, permit, permit, permit, deny", "Permit, deny, permit, deny, permit", "Deny, deny, permit, permit, deny"], correct:0, explanation:"The sequence implements this application's approved communication paths. Blocking direct web-to-database access reduces unnecessary exposure but does not by itself eliminate SQL injection carried through the application. Different architectures can have different legitimate flows; use explicit requirements rather than universal 'never' rules.", wrongFeedback:{1:"Rule 2 would permit direct internet access to the application tier, contrary to the policy.",2:"This blocks the required application-to-database service while allowing the forbidden direct web-to-database path.",3:"Denying rule 1 prevents the required public HTTPS service from being reached."}},
  p079: { ch:"4", objective:"4.5", cat:"Enterprise Security", difficulty:"medium", explanation:"These controls address different exposures and work together. Disk encryption reduces lost-device disclosure when keys are protected and the device is suitably secured; it does not prove there was no breach. EDR and application allowlisting have scope and bypass limitations. Patch management treats known flaws while testing compatibility and exceptions.", itemNotes:{i0:"Disk encryption protects stored data under the key and device-state assumptions; an unlocked session remains a different risk.",i1:"EDR correlates endpoint behaviour for detection and response, but cannot guarantee detection of every attack.",i2:"Allowlisting restricts execution according to policy; authorised tools and permissive rules can still be abused.",i3:"A host firewall filters permitted connections; malicious traffic can still use allowed destinations and ports.",i4:"Patching removes addressed vulnerabilities, not unknown flaws or every non-vulnerability initial-access method."}},
  p080: { ch:"4", objective:"4.3", cat:"Vulnerability Management", title:"Prioritise vulnerable dependencies using exposure", logData:"Validated dependency findings (illustrative, not live CVE advisories)\nA: remote code execution in an internet-facing component; reachable vulnerable path; active exploitation reported; approved fix available\nB: high-severity flaw in an isolated test component; vulnerable path currently disabled; fix available\nC: moderate-severity flaw requiring local access; fix available\nD: unmaintained package with no confirmed exploitable flaw in this assessment\nEmergency change and containment procedures are available.", question:"Which immediate plan best addresses the stated risk?", choices:["Treat C first solely because its update is easiest", "Prioritise A through the emergency process; apply verified temporary restrictions while testing and deploying its fix", "Replace D before addressing any confirmed exploitable finding", "Treat B first solely because test environments can tolerate downtime"], explanation:"A combines confirmed reachability, active exploitation and an exposed critical path. Use the emergency process to contain exposure and deploy a verified fix, then confirm effectiveness. A WAF signature can be an imperfect interim layer, not a guarantee of stopping all variants. Keep the remaining findings tracked; severity or a famous vulnerability name alone does not establish priority.", wrongFeedback:{0:"Ease of installation does not outweigh A's demonstrated immediate exposure.",2:"Unmaintained software creates lifecycle risk, but the supplied evidence makes A the immediate treatment priority.",3:"Downtime tolerance is useful for scheduling, not a reason to ignore the higher active production exposure."}},
  p057: { objective:"1.4", difficulty:"medium", title:"Verify a downloaded package's signature", scenario:"An engineer has securely obtained and verified the vendor's signing-key fingerprint. The package and detached signature are ready. Choose the operation that checks whether the signature matches the package using that trusted public key.", question:"Which operation meets the verification requirement?", answer:"Available files: package.tar.gz, package.tar.gz.sig\nTrusted vendor public key imported; fingerprint independently verified.\nPackage signature verification has not yet been performed.", choices:["Verify the detached signature against the package using the trusted vendor public key", "Encrypt the package using the vendor public key", "Sign the package using the engineer's own private key", "Hash the package and compare the result with its filename"], explanation:"Signature verification checks the signed data with the expected trusted public key. It provides integrity and origin evidence under the signing-key trust assumptions, not a guarantee that software is safe or that a key was never compromised. Importing an unverified key is insufficient. The exercise tests the operation rather than memorisation of a GPG command.", wrongFeedback:{1:"Encryption protects confidentiality for a recipient; it does not verify the received vendor signature.",2:"A new engineer signature says nothing about whether the received vendor signature was valid.",3:"A filename is not an authenticated reference digest or signature."}},
  p058: { ch:"4", objective:"4.6", question:"Which change directly prevents selection of passwords already known to be compromised?", choices:["Increase the minimum length by one character", "Screen proposed passwords against a compromised-password blocklist", "Require a new password every 30 days regardless of compromise", "Replace the password blocklist with personal security questions"], explanation:"A compromised-password blocklist directly addresses the specified problem. Also review the wider policy: NIST SP 800-63B-4 distinguishes single-factor minimum length from passwords used with MFA and rejects arbitrary periodic changes and composition rules in its scope. Do not interpret this one improvement as approval of the remaining example policy.", wrongFeedback:{0:"A breached password can still meet a longer minimum length; this does not check known compromise.",2:"Calendar-driven changes do not reliably exclude already compromised choices and can encourage predictable variations.",3:"Security questions do not screen password choices and can create a weak recovery path."}},
  p060: { objective:"1.1", difficulty:"easy", diagram:"Architect's classifications\n1. Firewall blocks prohibited inbound Telnet: preventive\n2. IDS reports suspected port scanning: detective\n3. Restore ransomware-damaged files from clean backup: preventive\n4. Encrypt stored files with protected keys: preventive", explanation:"The restoration action is corrective/recovery work after damage, not prevention of the original ransomware execution. The other classifications describe their stated functions. Controls reduce or address risk; calling one preventive does not mean it stops every incident.", wrongFeedback:{0:"Blocking a prohibited connection is a preventive function, so that classification fits.",1:"An IDS reporting activity performs detection; it need not actively block it.",3:"Stored-data encryption can prevent unauthorised reading when the adversary lacks keys, so the stated preventive function fits."}},
  p061: { objective:"2.2", targets:[{id:"t0",label:"Broad fraudulent email campaign impersonating a trusted entity"},{id:"t1",label:"Deceptive voice call seeking information or action"},{id:"t2",label:"Deceptive SMS seeking information or action"},{id:"t3",label:"Message tailored to a particular person or group"},{id:"t4",label:"Compromise of a site the intended targets are likely to visit"}], explanation:"These examples distinguish communication channels, targeting and delivery location. Spear phishing is a targeted form of phishing, not limited to a particular OSINT source. A watering-hole compromise can redirect users or deliver malicious content; it does not guarantee silent infection of every visitor.", itemNotes:{i0:"This example is a broad email-phishing campaign; phishing as a broader concept is not defined solely by bulk volume.",i1:"Vishing uses voice communication to manipulate the recipient.",i2:"Smishing uses SMS/text-message delivery.",i3:"Spear phishing tailors a message to chosen targets rather than distributing the same generic lure broadly.",i4:"A watering hole places the attack on a site frequented by the intended audience."}},
  p062: { blankNotes:{b0:"SQL injection occurs when untrusted input changes the intended database command structure.",b1:"Executing stored attacker-controlled script in another user's page context is stored cross-site scripting.",b2:"CSRF induces an unwanted request using a victim's existing session authority; script injection is not required.",b3:"Directory traversal escapes the intended filesystem boundary through attacker-controlled path input."}},
  p064: { ch:"4", objective:"4.3", cat:"Vulnerability Management", scenario:"An organisation is starting a vulnerability programme. For this exercise it inventories assets, defines and executes authorised scanning, prioritises the resulting findings, applies approved fixes, then verifies them. Arrange the activities in that sequence.", items:[{id:"o0",label:"Define authorised scan scope and cadence, then collect findings"},{id:"o1",label:"Establish and validate the asset inventory"},{id:"o2",label:"Apply approved remediation in risk-priority order"},{id:"o3",label:"Prioritise validated findings using severity, exposure, exploitation and business impact"},{id:"o4",label:"Rescan and confirm the remediation is effective"}], explanation:"Inventory supports scope; scanning produces findings to validate and prioritise before treatment and verification. The operational cycle repeats as assets and threats change. A severity score alone is not business risk, and verification should also consider regression or service impact.", itemNotes:{o0:"Authorised scanning follows the initial inventory and supplies findings for analysis.",o1:"Inventory establishes which assets the programme needs to cover.",o2:"Apply risk-prioritised treatments through appropriate approval and change processes.",o3:"Validated findings need business and threat context before remediation priorities are assigned.",o4:"Verification confirms that the treatment works; a successful installation message alone is insufficient."}},
  p066: { objective:"2.4", difficulty:"medium", question:"Which observation specifically suggests periodic beaconing and merits correlation with process telemetry?", diagram:"Proxy and DNS summary for WORKSTATION-07\n1. Small connections to an unfamiliar external endpoint roughly every 300 seconds, including nights\n2. Approved collaboration-service requests correlated with user sessions\n3. Unusually long encoded-looking DNS labels with elevated query volume\n4. One large upload to a file-sharing service\nThe endpoint also runs legitimate scheduled agents. No destination or process has yet been classified.", choices:["Repeated small connections at roughly 300-second intervals", "Session-correlated collaboration-service requests", "Long encoded-looking DNS labels with elevated query volume", "A single large file-sharing upload"], explanation:"Regular small connections suggest beaconing, but scheduled legitimate agents can behave similarly even while a user is away. Correlate the responsible process, destination reputation and baseline. The unusual DNS and large upload also warrant investigation; neither is the described periodic-beacon pattern and neither is automatically harmless.", wrongFeedback:{1:"This pattern is less specifically suggestive of autonomous periodic beaconing; approved-service traffic still needs context.",2:"Unusual encoded-looking DNS traffic may suggest tunnelling, but it does not establish the periodic connection pattern asked about.",3:"A large upload can be authorised transfer or exfiltration; a single event does not establish repeated beaconing."}},
  p067: { ch:"4", objective:"4.5", cat:"Enterprise Security", blanks:[{id:"b0",sentence:"___ publishes domain policy identifying authorised SMTP sending sources for the envelope identity.",answer:"SPF",hint:"DKIM, DMARC, SPF, S/MIME"},{id:"b1",sentence:"___ signs selected message headers and a body hash, enabling verification under a signing domain's published key.",answer:"DKIM",hint:"SPF, DMARC, DKIM, TLS"},{id:"b2",sentence:"___ checks alignment with the visible From domain and publishes requested handling and reporting policy.",answer:"DMARC",hint:"SPF, DKIM, DMARC, S/MIME"}], explanation:"SPF authenticates sending authorisation for an envelope identity, not the visible From address by itself. DKIM validates the signed content and signing domain, not a human sender's identity or harmlessness. DMARC passes when at least one SPF or DKIM result both passes and aligns with the visible From domain; it does not require both. Deploy and monitor carefully before enforcing a restrictive policy.", blankNotes:{b0:"SPF evaluates the connecting sender against the envelope domain's policy; it does not sign message contents.",b1:"DKIM uses a domain's cryptographic signature over selected headers and a body hash; it is not encryption.",b2:"DMARC adds visible-From alignment and requested policy/reporting to SPF/DKIM authentication results."}},
  p068: { choices:["Render untrusted text with context-appropriate encoding, sanitise any intentionally allowed HTML, and add restrictive CSP", "Encrypt the comment database without changing browser rendering", "Require HTTPS and HSTS without changing comment handling", "Set HttpOnly on session cookies without changing comment rendering"], explanation:"Use safe rendering or encoding for the actual insertion context. If users are intentionally allowed to submit HTML, apply a maintained allowlist sanitizer. A restrictive CSP adds defence in depth. HttpOnly can limit cookie theft but does not stop injected code from acting within the user's session.", wrongFeedback:{1:"Database encryption protects stored data under particular threats; it does not make rendered attacker HTML safe.",2:"HTTPS and HSTS protect transport/use of HTTPS, not execution of malicious stored comments.",3:"HttpOnly restricts script access to cookies but does not prevent the script from executing or making session-authorised requests."}},
  p048: { difficulty:"medium", scenario:"The hospital has activated safe downtime procedures. Its approved BIA assigns these recovery targets: ICU monitoring 15 minutes, EHR 1 hour, secure email 4 hours, payroll 24 hours, financial reporting 48 hours, public website 72 hours. Assume dependencies are available and resources permit one restoration at a time. Order by these approved targets.", explanation:"Use the supplied BIA and recovery targets, not a universal ranking of hospital applications. Safety, dependencies and clinical downtime arrangements shape the actual plan. The stated targets produce ICU, EHR, email, payroll, reporting, website; another organisation's BIA can legitimately differ.", itemNotes:{a:"The EHR has the second-shortest stated target, one hour.",b:"Payroll's 24-hour target follows email and precedes reporting.",c:"ICU monitoring has the shortest target and stated immediate safety importance.",d:"The website has the longest approved target here, 72 hours.",e:"Secure email's four-hour target places it after EHR and before payroll.",f:"Reporting has a 48-hour target, between payroll and the website."}},
  p049: { difficulty:"medium", question:"Which change set directly addresses deprecated protocols and legacy cipher configurations while retaining modern HTTPS support?", choices:["Disable TLS 1.0/1.1 and legacy static-RSA/3DES suites; retain approved TLS 1.2 ECDHE-AEAD suites and TLS 1.3", "Disable TLS 1.3 and retain TLS 1.0 for the broadest compatibility", "Change only the certificate expiry date while retaining every current suite", "Add HSTS but leave the deprecated protocol and cipher settings unchanged"], explanation:"Remove deprecated TLS versions and legacy suites while validating required client compatibility. Static RSA key exchange lacks forward secrecy: later compromise can expose recorded sessions negotiated with those suites, not every session irrespective of key exchange. RSA signatures used with ECDHE are different from static RSA key exchange. HSTS is useful additional protection but does not repair the listed protocol and cipher settings.", wrongFeedback:{1:"Disabling the modern protocol and retaining a deprecated version moves the configuration in the wrong direction.",2:"A certificate lifetime change does not remove deprecated versions or static-RSA and 3DES suites.",3:"HSTS encourages HTTPS use but does not make the server's enabled legacy protocols or suites suitable."}},
  p050: { blanks:[{id:"a",sentence:"A ___ is a network of decoy systems used to observe attacker activity.",answer:"Honeynet"},{id:"b",sentence:"___ records flow metadata such as addresses, ports and byte counts without full packet payloads.",answer:"NetFlow"},{id:"c",sentence:"A ___ occurs when a tool correctly flags genuinely malicious activity.",answer:"True Positive"},{id:"d",sentence:"A ___ occurs when a tool incorrectly flags benign activity as malicious.",answer:"False Positive"},{id:"e",sentence:"___ models user and entity activity to identify deviations that warrant investigation.",answer:"User and Entity Behaviour Analytics"}], explanation:"A honeynet contains multiple decoy resources, unlike a single honeypot. Flow records give metadata rather than full payload inspection. True/false positives describe the relationship between the detection and ground truth. Behaviour analytics can highlight anomalies, but an anomaly is not by itself malicious and implementations need not all use the same machine-learning technique.", blankNotes:{a:"A honeynet is the collection/network of decoys, not simply another name for any individual honeypot.",b:"NetFlow describes flows; packet capture is needed when full captured payload content is required.",c:"A true positive is a correct positive classification of a real threat.",d:"A false positive is a positive alert for an event that is actually benign.",e:"UEBA compares activity with behavioural context; analysts still need to validate the significance of a deviation."}},
  p051: { objective:"4.9", cat:"Investigation Data Sources", wrongFeedback:{0:"PowerShell is also a legitimate administration tool; the behaviour and context, not its existence, drive suspicion.",2:"TCP 443 is commonly used for HTTPS but is also used by malicious tooling; it does not prove legitimacy.",3:"A document process launching hidden encoded PowerShell and retrieving code is suspicious; automation should be validated rather than assumed normal."}},
  p052: { objective:"1.4", targets:[{id:"t0",label:"CA certificate explicitly trusted as an anchor in this PKI"},{id:"t1",label:"Subordinate CA authorised to issue certificates under its issuer's constraints"},{id:"t2",label:"Signed request containing a public key and requested certificate attributes"},{id:"t3",label:"Service providing signed certificate revocation-status responses"},{id:"t4",label:"Issuer-signed list of revoked certificates with publication/freshness information"}], explanation:"Trust anchors require explicit trust, not merely a self-signature. Offline root keys and HSMs are common protective designs, not definitions applying to every deployment. CSRs do not contain the private key. OCSP responses may be cached or stapled and report status at a particular freshness point; neither OCSP nor a CRL alone performs every certificate validation check.", itemNotes:{i0:"A root's trusted status comes from its inclusion in the relying party's trust configuration.",i1:"An intermediate CA has delegated certificate-issuing authority subject to chain constraints.",i2:"A CSR binds the requested attributes and public key to a signature; it does not send the private key to the CA.",i3:"An OCSP responder supplies good, revoked or unknown status with signed timing information, not guaranteed instantaneous knowledge.",i4:"A CRL lists revocations for its defined scope; clients also check its signature and freshness."}},
  p054: { objective:"1.4", difficulty:"medium", blanks:[{id:"b0",sentence:"A ___ is dedicated cryptographic hardware that can generate and use protected keys within a controlled security boundary.",answer:"Hardware Security Module (HSM)",hint:"Key management server, Hardware Security Module (HSM), Key escrow service"},{id:"b1",sentence:"___ protects cryptographic key material using another key, with an appropriate wrapping scheme.",answer:"Key wrapping",hint:"Key stretching, Key wrapping, Key rotation"},{id:"b2",sentence:"___ produces key material from input secrets using a defined derivation function; password-based versions use salt and a configurable cost.",answer:"Key derivation",hint:"Key wrapping, Key escrow, Key derivation, Key rotation"}], explanation:"HSM protection depends on configuration and key policy; supported backup/export does not mean every key is universally non-exportable. Key wrapping can use symmetric mechanisms, not just an RSA public key. Password-based derivation schemes raise guessing cost; they do not prevent all brute force. Salts defeat useful reuse of precomputed work, while cost settings make each guess more expensive.", blankNotes:{b0:"An HSM is dedicated protected cryptographic hardware; a generic key-management service does not by itself imply that hardware boundary.",b1:"Wrapping protects another key; rotation replaces keys and derivation calculates key material from inputs.",b2:"A KDF derives key material. Password-based KDFs need appropriate salts and cost; not every KDF is deliberately slow or password-based."}},
  p055: { objective:"1.2", scenario:"This site's physical layout is: exterior perimeter, staffed lobby, data-centre entrance, an operations room inside the data centre, and locked racks inside that room. Arrange controls from outside to inside for this stated layout.", explanation:"Layer controls according to this site's supplied layout. An access-control vestibule reduces unauthorised following when appropriately designed and operated; it is not a guarantee that tailgating is impossible. Real sites can arrange rooms and controls differently.", itemNotes:{o0:"Rack locks protect equipment inside the stated innermost room.",o1:"Fencing and exterior monitoring form this site's outer perimeter.",o2:"The entrance vestibule is after the lobby and before the internal operations room.",o3:"The room's biometric reader is inside the data-centre perimeter but outside its racks.",o4:"The staffed lobby is the first stated indoor checkpoint."}},
  p056: { ch:"4", objective:"4.6", cat:"Identity and Access Management", targets:[{id:"t0",label:"Resource owners can grant access subject to system policy"},{id:"t1",label:"Central label-based policy restricts access beyond the resource owner's discretion"},{id:"t2",label:"Permissions are grouped into roles assigned to users"},{id:"t3",label:"Policy evaluates subject, resource and environmental attributes"},{id:"t4",label:"Access follows administrator-defined conditions or rules"}], explanation:"These models describe how access decisions are made, not an inherent ranking from least to most secure. Implementations can combine models. Mandatory access control is not synonymous with one specific confidentiality model, and Zero Trust is broader than ABAC alone.", itemNotes:{i0:"Discretionary control gives the owner a role in assigning access within the system's constraints.",i1:"Mandatory control enforces central label/policy decisions that ordinary resource owners cannot override.",i2:"Role-based control groups permissions by role rather than assigning every permission separately to each person.",i3:"Attribute-based control evaluates contextual attributes against policy.",i4:"Rule-based control applies specified conditions; some implementations overlap with other policy-driven models."}},
  p036: { targets: [{id:"1",label:"Extorts a victim by denying access to data or systems"},{id:"2",label:"Replicates itself and spreads between systems"},{id:"3",label:"Masquerades as useful or legitimate software"},{id:"4",label:"Conceals malicious activity using privileged mechanisms"},{id:"5",label:"Records keystrokes to capture sensitive input"},{id:"6",label:"Executes a malicious action when a specified condition occurs"}], explanation:"Classify by the stated behaviour, not an assumption that malware families are mutually exclusive. Ransomware need not encrypt files, worms do not all require the same exploit, and rootkits are not limited to the OS kernel.", itemNotes:{a:"Ransomware uses denied access and a payment demand; some campaigns also steal data for extortion.",b:"A worm's defining property is self-replication and spread, unlike a Trojan's disguise.",c:"A Trojan presents itself as legitimate or useful software to induce execution.",d:"Rootkits hide activity through privileged mechanisms, including but not limited to kernel modifications.",e:"A keylogger captures keyboard input; the mechanism can be software or hardware.",f:"A logic bomb is conditional malicious execution, not necessarily a particular calendar date."}},
  p037: { difficulty:"easy", diagram:"Password storage pseudocode\n[A] Create stored value: encoded = base64_encode(password)\n[B] Verification: compare base64_encode(submitted_password) with stored value\n[C] Database: username and encoded value\n[D] Transport: HTTPS required", hotspots:[{id:"a",label:"[A] Stored-value creation",correct:true},{id:"b",label:"[B] Verification",correct:false},{id:"c",label:"[C] Record structure",correct:false},{id:"d",label:"[D] Transport",correct:false}], question:"Which change most directly protects passwords if an attacker reads the database?", choices:["Store a unique salt and a cost-tuned password hash; verify with the matching password-hashing library", "Keep base64 storage but compare the strings in constant time", "Rename the password column and restrict its display in the administration UI", "Keep base64 storage but require TLS 1.3 for all client connections"], explanation:"Base64 is reversible encoding, not password protection. Use a suitable password-hashing scheme with a unique salt and appropriate cost, such as Argon2id where supported. Constant-time verification, access controls and TLS address other risks but cannot make a copied base64 value resistant to decoding.", wrongFeedback:{1:"Constant-time comparison addresses a timing side channel, not offline decoding of the stolen value.",2:"Column names and UI visibility do not protect contents from an attacker who can read the database.",3:"TLS protects network transport; it does not transform reversibly encoded values already stored in the database."}},
  p038: { ch:"5", objective:"5.5", cat:"Audits and Assessments", scenario:"The signed rules of engagement define this test's sequence: authorisation and passive reconnaissance, active discovery, controlled exploitation, impact assessment, verified cleanup, then delivery of the final report. Arrange the activities to follow that agreed plan.", explanation:"Follow the authorised scope and agreed sequence. Reporting and safety communication occur throughout the engagement; the final report here follows verified cleanup. Real methodologies can iterate, and this exercise does not imply that a particular ordering is frequently tested on the exam.", itemNotes:{a:"Attempt only authorised exploits after identifying relevant services and vulnerabilities.",b:"Obtain authorisation, agree safety limits and gather permitted reconnaissance before active testing.",c:"Deliver the final report with findings, evidence, limitations and remediation recommendations after this plan's cleanup verification.",d:"Active discovery identifies reachable services for the subsequent authorised tests.",e:"Assess the permitted impact of a confirmed compromise without exceeding scope.",f:"Remove and verify removal of test artefacts, coordinating any exceptions with the owner."}},
  p039: { choices:["Document 1", "Document 2", "Document 3", "Document 4"], explanation:"Document 2 defines mandatory, specific requirements and is a standard. Document 1 states high-level policy, Document 3 is an operating procedure, and Document 4 is optional guidance. These are useful distinctions, not a universal four-step organisational hierarchy. The password timings are this scenario's policy, not a universal regulatory requirement."},
  p040: { difficulty:"medium", logData:"Normalised endpoint and authentication timeline\n14:15:02 WS-042: jsmith network logon succeeds (4624)\n14:15:10 WS-042: privileged logon recorded (4672)\n14:15:11 WS-042: powershell.exe starts a file named mimikatz.exe (4688)\n14:15:14 WS-042: explicit Administrator credentials used (4648)\n14:15:20 WS-042: remote-execution tool starts with DC-01 as target\n14:15:25 DC-01: Administrator network logon succeeds from WS-042\nNo password/hash extraction telemetry is available in this excerpt.", question:"Which conclusion is best supported by this evidence?", choices:["The Administrator password was recovered in plaintext", "Possible credential access followed by lateral movement warrants investigation; the authentication technique is not proven", "Event 4672 by itself proves an exploit elevated the user's privileges", "Event 4648 conclusively identifies pass-the-hash authentication"], explanation:"The sequence warrants prompt investigation of possible credential access and lateral movement. A tool name is not proof of successful dumping. Event 4672 records special privileges assigned to a logon, and 4648 records attempted use of explicit credentials; neither alone proves exploitation or pass-the-hash. Correlate authentication protocol, process access, commands and authorised activity.", wrongFeedback:{0:"The excerpt contains no evidence that plaintext passwords were recovered.",2:"Privileged accounts can legitimately generate 4672 at logon without exploiting anything.",3:"Explicit-credential use is not a conclusive marker of hash-based authentication; additional telemetry is needed."}},
  p041: { targets:[{id:"1",label:"Disk or file encryption with separately protected keys"},{id:"2",label:"Authenticated TLS for an HTTPS connection"},{id:"3",label:"An isolated trusted execution environment for sensitive computation"},{id:"4",label:"Backup-media encryption before off-site shipment"},{id:"5",label:"Recipient-key message encryption using S/MIME"}], explanation:"Choose a control for the stated context; the categories overlap. Backup tapes are data at rest and email can be in transit or stored. TLS protects HTTPS, while SFTP uses SSH rather than TLS. Isolated execution can reduce exposure during processing, but does not remove all side-channel or application risks.", itemNotes:{a:"Disk/file encryption protects stored data if the attacker lacks the decryption key; unlocked authorised sessions remain a separate risk.",b:"Authenticated TLS protects the HTTPS channel against interception and modification; obsolete SSL is not the recommended protocol.",c:"A trusted execution environment can isolate selected computation from other software; ordinary disk encryption does not protect already decrypted memory.",d:"Encrypt and protect keys before tapes leave controlled custody; transport also needs physical accountability.",e:"S/MIME message encryption can protect the message beyond a single mail-transport connection when recipient keys are managed correctly."}},
  p042: { objective:"2.2", cat:"Threat Vectors", title:"Identify the point of malicious code execution", scenario:"A finance user receives a phishing email containing a malicious PDF. Endpoint telemetry confirms that opening the PDF exploits the reader and starts unauthorised code. A loader then establishes persistence and contacts an external service. Later, investigators confirm unauthorised payroll-data transfer.", question:"Which observed event first demonstrates successful exploitation in this sequence?", choices:["The email arriving in the mailbox", "An outbound connection from the installed loader", "The reader vulnerability causing unauthorised code execution", "The later unauthorised payroll-data transfer"], explanation:"The confirmed code execution caused by the reader flaw is successful exploitation. Delivery alone is an attempt; command-and-control and data theft occur later in this stated sequence. The question tests a document-based threat vector without requiring memorisation of an off-blueprint named kill-chain model.", wrongFeedback:{0:"Receiving a malicious document does not itself show the vulnerability was triggered.",1:"The loader's network activity occurs after the exploit has executed code here.",3:"Data theft is a later impact, not the earliest demonstrated exploitation event."}},
  p043: { blanks:[{id:"a",sentence:"The ___ documents who collected, handled and transferred evidence.",answer:"Chain of Custody"},{id:"b",sentence:"A ___ suspends routine disposal of potentially relevant information when preservation duties arise.",answer:"Legal Hold"},{id:"c",sentence:"___ proactively searches for threats that may have evaded automated detection.",answer:"Threat Hunting"},{id:"d",sentence:"A ___ exercise discusses a simulated incident without conducting live system actions.",answer:"Tabletop"},{id:"e",sentence:"___ is the acquisition and examination of digital evidence using documented investigative methods.",answer:"Digital Forensics"}], explanation:"Evidence documentation and preservation support investigation and legal processes. A custody gap does not automatically make evidence inadmissible in every jurisdiction. A legal hold can be issued internally to meet a preservation duty; it does not always require a court order. Threat hunting tests hypotheses, and a tabletop tests plans through discussion.", blankNotes:{a:"Custody records establish handling continuity and help investigators assess evidence integrity.",b:"A legal hold prevents relevant information from being destroyed through ordinary retention processes while the duty applies.",c:"Threat hunting seeks otherwise undetected activity through hypotheses and evidence, not indiscriminate assumptions that every event is malicious.",d:"A tabletop is discussion-based; a live simulation can involve operational actions.",e:"Digital forensics uses documented collection, examination and analysis to support defensible findings."}},
  p044: { difficulty:"medium", scenario:"A required design separates public web services from internal databases. The approved architecture specifically requires two independently managed firewall devices: an outer perimeter and an inner boundary. Only authorised web-to-database traffic may cross the inner boundary. Select the design that meets these requirements.", currentConfig:"Existing design: one flat segment contains the web server, database and internal applications. There is no effective segmentation policy between these systems.", options:["One firewall with separate internet, DMZ and internal interfaces and restrictive inter-zone rules", "One perimeter firewall with web, database and application servers on a flat trusted segment", "Two firewalls with the database in the public zone and unrestricted public access to its service", "Two independently managed firewalls with the web server between them and narrowly permitted web-to-internal-database traffic"], explanation:"D meets this organisation's stated two-device and traffic-isolation requirements. A well-configured single multi-interface firewall can also implement a valid DMZ, but does not meet the specified independence requirement. Two devices are not automatically more secure; configuration, management and actual permitted paths matter.", wrongFeedback:{0:"This is a valid general DMZ design, but it does not supply the two independently managed devices required here.",1:"The flat segment lacks the required separation and filtering between web and internal services.",2:"Unrestricted public database access violates the explicit access policy; two devices do not compensate for permissive rules."}},
  p045: { ch:"4", objective:"4.6", cat:"Identity and Access Management", answer:"Authentication diagnostic\nClient clock: 10:30:00 UTC\nKDC clock: 10:36:45 UTC\nConfigured acceptable skew: 5 minutes\nAuthentication rejected: timestamp outside configured tolerance", question:"Why does synchronising the client clock help in this Kerberos environment?", choices:["It lengthens every ticket's validity until the clocks diverge again", "It enables timestamp freshness checks within the configured tolerance, alongside replay-cache checks", "It replaces the requirement to validate service-ticket keys", "It makes a captured authenticator safely reusable during the tolerance window"], explanation:"Kerberos uses time-sensitive authenticators and ticket validity checks. Clock synchronisation allows freshness checks to work; replay caches provide additional protection against reuse, including within the allowed skew. Five minutes is a common configurable tolerance, not a universal protocol requirement or a promise that replay is allowed for five minutes.", wrongFeedback:{0:"Clock synchronisation does not arbitrarily extend a ticket's defined start/end times.",2:"Correct time does not replace cryptographic ticket and authenticator validation.",3:"Replay detection can reject a reused authenticator even when its timestamp falls within the permitted skew."}},
  p046: { items:[{id:"a",label:"Buy cyber insurance subject to coverage terms and exclusions"},{id:"b",label:"Discontinue the payment activity that creates the identified fraud risk"},{id:"c",label:"An authorised risk owner documents acceptance of the residual exposure"},{id:"d",label:"Deploy MFA to reduce account-compromise likelihood"},{id:"e",label:"Contractually allocate specified payment-processing losses to a service provider"}], explanation:"These are the primary responses illustrated; real decisions can combine them. Insurance and contractual allocation shift only specified losses or responsibilities. Outsourcing does not automatically transfer all risk or relieve a merchant of its own PCI DSS duties. Avoidance stops the defined activity, not every risk the organisation faces.", itemNotes:{a:"Insurance transfers covered financial losses within the policy's limits, exclusions and conditions.",b:"Discontinuing the source activity avoids that activity's future exposure, while other risks can remain.",c:"Acceptance is an informed risk-owner decision; documentation alone does not reduce exposure.",d:"MFA mitigates likelihood rather than guaranteeing prevention or transferring losses.",e:"Explicit contractual allocation can transfer defined exposure; provider certification alone does not establish that transfer."}},
  p047: { difficulty:"medium", title:"Investigate public cloud storage exposure", logData:"Normalised cloud-storage audit and object-access records\n09:00:01 administrator identity changes the HR container policy to allow anonymous object reads\n09:00:15 anonymous request downloads employee_salaries.csv successfully\n09:00:17 anonymous request downloads hr_export.csv successfully\n09:01:44 anonymous request downloads employee_identifiers.csv successfully\n09:15:00 administrator identity removes anonymous access\nAccess records show 147 successful anonymous object downloads during this interval.", question:"Which conclusion and preventive control best fit the evidence?", choices:["A password guessing attack is proven; increase only the administrator password length", "Sensitive objects were anonymously accessible; enforce an effective organisation-level guardrail against public access", "A compromised vendor is proven; replace the storage vendor", "The named administrator deliberately leaked the files; punish the account owner immediately"], explanation:"The policy and successful anonymous reads establish unauthorised exposure under the assumed private-data policy. Enforce and test a non-bypassable public-access guardrail at the appropriate scope, preserve evidence and investigate the change. Logs identify an identity used, not the human actor or intent. This vendor-neutral exercise does not mistake a bucket-listing ACL for object-read permission.", wrongFeedback:{0:"These records do not establish password guessing; password length alone does not prevent an authorised identity from making data public.",2:"No evidence in this excerpt identifies vendor compromise as the cause.",3:"An account's recorded action does not prove the account owner's intent or exclude stolen credentials and automation."}},
  p001: { scenario: "An approved scan of 10.0.0.20 finds the services below. The deployment policy permits SSH and port 8080 only from management hosts, HTTP solely for HTTPS redirection, and HTTPS for users. These restrictions are verified. MySQL remains reachable from every internal subnet, though only the application subnet needs it.", question: "Which remaining exposure should be corrected?", choices: ["Disable the restricted SSH service", "Restrict MySQL to the authorised application sources", "Remove the verified HTTP-to-HTTPS redirect", "Disable the restricted administration service on 8080"], explanation: "The evidence identifies MySQL as the unresolved access-policy violation. Restrict its sources and verify the effective rule. A scan of a private address alone does not prove public internet exposure, and service names alone do not establish a universal risk ranking.", wrongFeedback: {0: "SSH already meets the stated management-source restriction and has a business purpose.", 2: "The HTTP service is explicitly verified as the required redirect, not the unresolved policy gap.", 3: "Port 8080 is already restricted according to the supplied policy; the remaining broad exposure is MySQL."} },
  p002: { scenario: "You obtain a SHA-256 reference through an authenticated vendor channel. Compute the downloaded update's digest and compare it with this reference: 9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08.", answer: "SHA-256 comparison for update_package.zip\nComputed: 9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08\nTrusted reference: 9f86d081884c7d659a2feaa0c55ad015a3bf4f1b2b0b822cd15d6c15b0f00a08\nMatch: yes", choices: ["Confidentiality", "Integrity", "Availability", "Non-repudiation"], explanation: "Matching a strong hash against a trusted reference provides integrity evidence. It does not encrypt the file, guarantee the absence of malicious content or mathematically exclude every collision. Trust in the reference is essential; a replaced file and replaced unsigned digest could match.", wrongFeedback: {0: "The file's contents need not be encrypted for their digest to match.", 2: "The comparison evaluates content consistency, not a service's uptime or recoverability.", 3: "An ordinary hash is not attributable signature evidence; anyone can compute a digest."} },
  p003: { difficulty:"medium", objective:"4.9", scenario:"A workstation has unexplained outbound traffic. Correlate the simulated process and connection records to choose the strongest reason to investigate PID 4892. File signatures, executable paths and destination reputation have not yet been checked.", question:"Which assessment is BEST supported by the available evidence?", answer: "PROCESS LIST\nPID   Name              CPU%  Memory  Parent\n1024  explorer.exe       0.2  45 MB   userinit.exe\n4892  svchost32.exe     18.0  210 MB  cmd.exe\n\nNETWORK CONNECTIONS\nPID   Local                 Remote             State\n4892  192.168.1.100:54321    198.51.100.5:443   ESTABLISHED", choices:["The remote port identifies an encrypted browser session, so investigate browser extensions first", "The look-alike name, shell launch and outbound connection together warrant validating this executable", "The process name identifies a compatibility service, so compare its CPU use with other 32-bit services", "The established connection identifies an inbound service, so investigate unsolicited client access first"], explanation:"The combined process name, launch context and network activity justify investigating this executable. Correlate its path, signature, command line and related events before concluding it is malware. TCP 443 does not establish the application, encryption or intent; a process name does not establish legitimacy. The evidence supports investigation, not a confirmed compromise.", wrongFeedback:{0:"TCP 443 is commonly used for HTTPS, but the port alone does not identify a browser or prove encryption. The record links the connection to PID 4892, so validate that executable.",2:"A name resembling a Windows service is not evidence that it is an approved compatibility service. The suffix does not reliably identify executable architecture; validate the file and launch context.",3:"ESTABLISHED describes connection state, not which endpoint initiated it. The scenario reports outbound traffic; this record does not establish an inbound listening service."} },
  p004: { scenario: "Arrange the high-level activities in this team's simplified response plan. Preparation occurs before the incident; the plan calls for initial analysis, containment, removal of the cause, validated restoration, then a retrospective. Real incidents can revisit activities.", explanation: "This exercise uses a simplified teaching sequence, not a claim that NIST defines six isolated phases. Analysis, containment and other work can overlap or repeat as evidence changes. Choose the order specified by this plan, while balancing safety and evidence preservation.", itemNotes: {a: "The retrospective uses the incident record to improve plans after the response.", b: "Initial containment limits spread and impact while responders plan safe removal.", c: "Initial analysis establishes the incident and scope needed for proportionate containment.", d: "Eradication removes malicious components and addresses the entry condition.", e: "Recovery restores clean operations and checks for recurrence after remediation.", f: "Preparation establishes contacts, authority and tools before the incident starts."} },
  p005: { targets: [{id:"1",label:"Uses the same shared secret to encrypt and decrypt"},{id:"2",label:"Uses a public/private key pair for supported encryption and decryption"},{id:"3",label:"Computes a fixed-length digest without a decryption operation"},{id:"4",label:"Signs with a private key; verifies with the corresponding public key"},{id:"5",label:"Increases the computational cost of deriving a password value"}], explanation: "Choose the tool for its purpose: encryption for confidentiality, hashing for a digest, signatures for attributable integrity evidence, and stretching for costlier password guesses. Public-key algorithms have different capabilities; not every elliptic-curve scheme encrypts. Trust and key custody remain essential.", itemNotes: {a: "Symmetric encryption uses a shared secret; distributing and protecting it is part of the design.", b: "Supported asymmetric encryption uses the recipient's public key and corresponding private key, with identity verification of the public key.", c: "Hashing produces a digest. Guessing possible inputs is still possible even though there is no decryption key.", d: "A digital signature is generated and verified using the designated signature algorithm and key pair, not generic private-key encryption.", e: "A password-derivation work factor increases each guess's cost; it does not make weak passwords unguessable."} },
  p006: { items: [{id:"a",label:"Nation-state actor"},{id:"b",label:"Unskilled attacker"},{id:"c",label:"Hacktivist"},{id:"d",label:"Insider threat"},{id:"e",label:"Organised crime"}], targets: [{id:"1",label:"Acts to further a nation's strategic objectives"},{id:"2",label:"Relies heavily on existing tools with limited technical understanding"},{id:"3",label:"Motivated primarily by an ideological or political cause"},{id:"4",label:"Risk arising from someone with entrusted access"},{id:"5",label:"Organised group primarily pursuing illicit financial gain"}], explanation: "These are broad actor attributes, not definitive attribution rules. Nation-state activity does not require zero-days. Insiders may act maliciously or accidentally, and existing access controls should not simply assume they are trustworthy.", itemNotes: {a: "The national strategic objective identifies the category; funding and tools can vary.", b: "Limited technical understanding distinguishes an unskilled attacker, not whether every attack is noisy.", c: "The ideological motivation identifies hacktivism; technique alone does not.", d: "Entrusted access defines the insider context, not a universal claim that insiders are hardest to detect.", e: "Financial gain is the primary motive; ransomware is one possible technique, not a requirement."} },
  p007: { difficulty: "medium", diagram: "ALERT DASHBOARD\n[A] Approved firewall update completed; health checks normal.\n[B] Five failed SSH logins; investigation pending, no success in this extract.\n[C] Confirmed ransomware is actively encrypting files on the accounts server.\n[D] Missing security update on an internal app; no exploitation evidence currently available.", choices: ["Alert A", "Alert B", "Alert C", "Alert D"], explanation: "Confirmed ongoing destructive activity in C requires immediate coordinated response. Contain spread and stop harmful execution as safely as possible under the plan while preserving feasible evidence. B and D still need assessment; failed logins do not prove there has been no compromise, and internal exposure is not automatically low risk.", wrongFeedback: {0: "A reports expected completion and normal checks, unlike confirmed ongoing harm in C.", 1: "B merits investigation, but the supplied evidence supports prioritising confirmed active encryption.", 3: "D needs risk-based remediation; these facts do not outrank the confirmed destructive incident."} },
  p008: { diagram: "Illustrative pseudocode\n1: connection = open_database()\n2: supplied_name = request.username\n3: query = \"SELECT password_hash FROM users WHERE username='\"\n4: query = query + supplied_name + \"'\"\n5: record = connection.execute(query).first()\n6: if record and verify_password(request.password, record.password_hash):\n7:     return create_session_for_verified_user(record)", hotspots: [{id:"a",label:"Line 1",correct:false},{id:"b",label:"Lines 3–4",correct:true},{id:"c",label:"Line 5",correct:false},{id:"d",label:"Lines 6–7",correct:false}], choices: ["Line 1: opening a connection", "Lines 3–4: building SQL from untrusted input", "Line 5: executing a database operation", "Lines 6–7: verifying a password before creating a session"], explanation: "The concatenation lets input become SQL syntax. Parameterise the username lookup using the database driver's API, then verify the supplied password against its salted password-derived value. Do not replace this with plaintext password comparison in SQL. The pseudocode illustrates the data flow, not a complete production login implementation.", wrongFeedback: {0: "A database connection is needed; the stated flaw is construction of the query from input.", 2: "Execution is where unsafe SQL takes effect, but the identified source of the injection is the prior concatenation.", 3: "Password verification before session creation is appropriate; the query supplying the record must also be safe."} },
  p009: { scenario: "The response lead has approved this collection sequence for a stable suspected workstation: document the scene and clock first; then capture short-lived connection and process observations; then acquire RAM; finally image persistent storage. Arrange the listed tasks to follow that case plan. This is not a universal ranking among all volatile artefacts.", explanation: "Collect volatile evidence before actions that destroy it where safe and feasible. Ordering among RAM, connections and processes depends on the case, tools and risks. Here the approved plan defines the required order. Document tool impact, timestamps, integrity checks and custody; urgent containment may change collection priorities.", itemNotes: {a:"Persistent storage is imaged after volatile collection in this approved plan, using appropriate write protection and verification.", b:"The plan captures current connections early because they may end quickly.", c:"Initial photographs preserve the observed scene before interaction changes it.", d:"Process and handle observations are captured next under the stated plan.", e:"RAM acquisition follows these short live observations and precedes disk imaging in this case.", f:"Clock documentation establishes a reference for interpreting collected timestamps."} },
  p010: { difficulty: "medium", scenario: "Order these simplified milestones for a full TLS 1.2 ECDHE server-authenticated handshake, with no resumption or early data. The exercise groups related protocol messages; it is not a packet-by-packet TLS 1.3 sequence.", items: [{id:"a",label:"Exchange protected application data after Finished verification"},{id:"b",label:"Validate the server's certificate and signed key-exchange information"},{id:"c",label:"Receive the server's selected parameters, certificate and key-exchange information"},{id:"d",label:"Complete ephemeral agreement and derive the required traffic secrets"},{id:"e",label:"Send ClientHello with supported capabilities"}], explanation: "In this specified simplified flow, the client offers capabilities, receives and validates the server's authenticated parameters, completes key agreement and derives secrets, then exchanges application data after handshake verification. Other TLS versions and modes have different message ordering.", itemNotes: {a:"Application data follows successful handshake verification in this no-early-data example.", b:"Validate the received identity and signed parameters before relying on the peer.", c:"The server selects offered parameters; it does not simply return a list of all supported suites.", d:"The parties derive secrets from the agreed ephemeral exchange and handshake context.", e:"The client begins negotiation by advertising supported capabilities."} },
  p011: { explanation: "SLE estimates one incident's loss; ALE multiplies it by expected annual frequency. An ARO of 0.25 is an average rate, not a promise of exactly one event every four years. Use exposure factor as a fraction in multiplication. Compare expected loss reduction with costs over a consistent time horizon, alongside legal and operational needs.", blankNotes: {a:"Multiplying asset value by the fraction lost gives single loss expectancy (SLE).", b:"Multiplying single-event loss by annual frequency gives annualised loss expectancy (ALE).", c:"Occurrence refers to expected event frequency; ARO is a rate, not a certainty about scheduling.", d:"Exposure factor expresses the proportion or percentage of asset value lost; convert 40% to 0.40 when multiplying."} },
  p012: { explanation: "Phishing is deceptive messaging; voice and SMS variants are vishing and smishing. Spear phishing describes targeting, not a distinct transport. Do not infer a guaranteed frequency of these topics on a real exam.", blankNotes: {a:"The deceptive bank email is a phishing lure aimed at credential disclosure.", b:"The telephone voice channel distinguishes vishing.", c:"The SMS text channel distinguishes smishing.", d:"Personalised targeting of a named individual distinguishes spear phishing from a generic lure."} },
  p013: { scenario: "For this simplified first-match inbound ruleset, public HTTP and HTTPS must reach SERVER. SSH must reach SERVER only from 10.0.0.0/24. Established return traffic is handled separately. Deny all other new inbound traffic.", currentConfig: "RULE 1: ALLOW TCP ANY -> SERVER 80\nRULE 2: ALLOW TCP ANY -> SERVER 443\nRULE 3: ALLOW TCP ANY -> SERVER 22\nRULE 4: ALLOW IP ANY -> SERVER", options: ["ALLOW management -> SERVER 80,443,22; DENY ALL", "ALLOW ANY -> SERVER 80,443; ALLOW management -> SERVER 22; DENY ALL", "ALLOW ANY -> SERVER 80,443,22; DENY ALL", "DENY ALL; ALLOW ANY -> SERVER 80,443; ALLOW management -> SERVER 22"], explanation: "B permits required public web traffic, restricts management access and denies unmatched traffic. With first-match evaluation, permits must precede the final deny. Real deployments also require correct direction, protocol, destination and state handling.", wrongFeedback: {0:"Restricting web ports to management prevents the public web access required by the scenario.", 2:"This opens SSH to every source rather than the management subnet only.", 3:"The first deny matches all traffic, so subsequent permit rules cannot take effect."} },
  p014: { question: "Which pair of attempted attacks is supported by the request strings?", explanation: "SQL syntax in the parameter indicates attempted SQL injection; parent-directory sequences indicate attempted traversal. HTTP 200, response size or a 500 error alone do not prove exploitation or disclosure. Inspect response content and server-side evidence before confirming impact.", wrongFeedback: {0:"The shown strings indicate SQL manipulation and path traversal, not a demonstrated availability flood or browser script payload.", 2:"No credential-guessing sequence or deceptive message is shown.", 3:"These are web-request patterns, not evidence of a port scan or forged ARP mapping."} },
  p015: { question: "Which conclusion is justified by these authentication records without seeing passwords or session actions?", choices: ["Confirmed credential stuffing using a known breach list", "Multiple-source login attempts warrant investigation, especially the later success", "Confirmed use of exactly one password across all users", "Confirmed replay of a captured token"], explanation: "The records show failed attempts from several sources and a later success. Correlate source ownership, user activity, MFA and session behaviour; the excerpt alone cannot prove the success belongs to an attacker or distinguish spraying from stuffing or other guessing. Per-IP rate limits and per-account lockouts are different controls.", wrongFeedback: {0:"No breached credential list or reused pairs are shown.", 2:"Passwords are not logged here, so this excerpt cannot establish that every attempt used one common password.", 3:"No captured token or reuse evidence is provided."} },
  p016: { scenario: "An unmanaged IaaS service agreement assigns guest OS patching and database configuration to the customer. Investigation confirms entry through that VM's unpatched OS and default database password. Provider physical controls passed their review. Which party owned the failed tasks under this agreement?", choices: ["Provider: physical controls include all guest configuration", "Customer: the stated agreement assigns both tasks to it", "Both parties equally regardless of assigned duties", "Neither party because a breach occurred"], explanation: "The customer owns the two specified operational tasks under this agreement. Cloud security remains shared, and contracts or additional managed services can change allocations. This technical responsibility conclusion is not a complete legal liability determination.", wrongFeedback: {0:"Physical infrastructure responsibility does not include these guest tasks under the supplied agreement.", 2:"Shared responsibility allocates different duties; it does not automatically divide every failure equally.", 3:"An incident does not erase the explicit responsibility assignment."} },
  p017: { difficulty:"medium", objective:"5.2", scenario:"A retailer's optional telephone-order channel requires staff to record payment details on an unsupported system. Management decides the exposure is unacceptable and asks for a proposal that uses risk avoidance for this channel. The retailer can continue trading through its separate in-store channel.", question:"Which proposal BEST implements the requested risk response?", choices:["Replace the telephone-order system and train staff to handle the same orders securely", "Keep telephone orders and purchase insurance covering specified breach-related losses", "Stop accepting telephone orders and securely retire that channel's payment-processing workflow", "Keep telephone orders under an authorised, time-limited exception with a documented review date"], explanation:"Ending the defined telephone-order activity avoids its future operational exposure. Replacing its system while continuing the activity is mitigation; insurance transfers specified financial consequences; an authorised exception is acceptance. Retiring the channel still requires secure handling of existing records and outstanding obligations, and does not remove unrelated business risks.", wrongFeedback:{0:"Replacement and training reduce the risk while retaining the telephone-order activity. That is mitigation rather than the requested avoidance of this channel.",1:"Insurance transfers covered financial consequences subject to its terms. It does not stop the activity or remove all responsibilities and losses.",3:"A time-limited authorised exception accepts the exposure for that period; it does not end the risky activity. Acceptance must remain consistent with mandatory obligations."} },
  p018: { targets: [{id:"1",label:"Platform-bound key protection and support for measured boot"},{id:"2",label:"Dedicated cryptographic module protecting enterprise keys and operations"},{id:"3",label:"Authorised recovery arrangement holding protected key material"},{id:"4",label:"Issuer that signs certificates binding a public key to asserted identity"},{id:"5",label:"Protocol returning signed, time-bounded certificate status"}], explanation: "TPM implementations vary and need not be a soldered discrete chip. Measured boot records measurements; it is distinct from Secure Boot signature enforcement. A CA may be intermediate rather than a trust anchor. OCSP status must be checked for freshness rather than assumed instantaneous.", itemNotes: {a:"A TPM supports platform-related measurements and key protection, not the same role as a fleet-wide HSM appliance.", b:"An HSM provides a protected cryptographic boundary for supported key operations.", c:"Escrow provides controlled recovery but adds custody and unauthorised-access risks requiring governance.", d:"A CA signs certificates; trust still depends on a validated path to an accepted anchor.", e:"OCSP conveys certificate status with validity times; responders and clients need sound freshness policies."} },
  p019: { explanation: "Voice and SMS distinguish vishing and smishing. Spear phishing describes targeting, and whaling is targeting high-profile decision-makers. These categories can overlap: an executive-targeted lure may also be delivered by voice or SMS.", blankNotes: {a:"A deceptive email soliciting bank credentials is phishing.", b:"The voice call makes this vishing.", c:"The deceptive lure delivered by SMS is smishing, rather than a voice-based vishing call.", d:"A specifically tailored recipient lure is spear phishing.", e:"The high-profile executive target distinguishes whaling within targeted phishing."} },
  p020: { scenario: "Follow this team's simplified workflow: discover and confirm findings, categorise, prioritise by risk, remediate, validate, then issue the final completion report. Preliminary findings and urgent risks are communicated throughout; the reporting item here specifically means the final validated outcome.", items: [{id:"a",label:"Validate remediation with appropriate checks"},{id:"b",label:"Discover and confirm applicable findings"},{id:"c",label:"Issue the final validated-outcome report"},{id:"d",label:"Prioritise by severity, exposure and business impact"},{id:"e",label:"Implement approved remediation or interim mitigation"},{id:"f",label:"Categorise confirmed findings"}], explanation: "The sequence follows the explicitly supplied workflow. Communicate urgent findings before remediation too; reporting is not universally postponed until the end. Verification may include rescanning, configuration inspection and testing rather than only trusting a patch-success message.", itemNotes: {a:"Validation checks whether the fix actually resolved the applicable issue.", b:"Discover and validate applicability before ranking a supposed vulnerability.", c:"This final report records validated outcomes, distinct from earlier risk communications.", d:"Priority combines technical and local risk context rather than CVSS alone.", e:"Apply the approved change and manage any interim mitigation separately.", f:"Classification organises confirmed weaknesses before risk-based prioritisation."} },
  p021: { scenario: "An IDS observes network traffic and sends an alert about suspicious patterns. It is deployed out of band and does not block packets. Classify this specific mechanism by category and main function.", explanation: "The IDS is a technical control with a detective function. Detection can occur during an event; it need not wait until damage is complete. Blocking would require a separate enforcement mechanism or an inline prevention configuration." },
  p022: { scenario: "For this conventional unmanaged IaaS agreement, the provider operates physical infrastructure and the hypervisor; the customer manages its guest software. Select the highest provider-managed compute layer in the simplified diagram.", question: "Which labelled layer is the highest provider-managed compute layer under this agreement?", explanation: "A identifies the hypervisor in this stated IaaS allocation. Customers normally manage guest software, configuration and data, while other responsibilities such as identity configuration remain shared according to the service. Extra managed services can change this allocation." },
  p023: { scenario: "This Linux host's approved baseline permits root read/write and the dedicated shadow group read access to /etc/shadow, with no other-user access. The scan shows mode 644. Interpret the unexpected other-user permission before applying the host-specific baseline.", answer: "Observed: -rw-r--r--  root root  /etc/shadow\nMode: 644\nApproved baseline: root:shadow, mode 640\nReview group membership and ACLs as well as mode bits.", explanation: "The last 4 grants read access through the other-user permission bits, exposing password-derived values to offline guessing. For this host, the supplied baseline is root:shadow 640. Other platforms may use different approved settings; chmod alone does not change file ownership." },
  p024: { explanation: "Match each primary capability rather than assuming a product can perform only one function. Passive IDS alerts; inline IPS can block. DLP covers policy-governed data use and movement, not just outbound internet traffic. WAF HTTPS inspection requires appropriate visibility and does not stop every application flaw.", itemNotes: {a:"SIEM correlates records from several sources for investigation and alerting.", b:"A passive IDS observes suspicious activity without inline enforcement.", c:"An inline IPS can block traffic matching its configured prevention decisions.", d:"DLP evaluates sensitive-content handling and may alert or block according to policy.", e:"A WAF provides HTTP-aware inspection, subject to decoding and TLS visibility."} },
  p025: { logData: "Normalised incident timeline (multiple sources)\n14:23:00 Security process audit: vssadmin.exe delete shadows /all /quiet\n14:23:06 EDR file telemetry: unknown_svc.exe rapidly rewrites finance documents; analysis confirms encryption\n14:23:12 Security process audit: cipher.exe /w:C:\\ launched by unknown_svc.exe\n14:23:18 System service log: WindowsUpdater service installed from C:\\ProgramData\\svcupdate.exe\n14:24:01 Proxy log: HTTPS upload to 192.0.2.55, size 2.4 MB; content not captured", choices: ["Treat this as a routine update solely because the service name contains Windows", "Invoke the ransomware response plan and promptly contain the affected host", "Treat cipher.exe as proof of an antivirus scan", "Conclude the upload alone proves which data was stolen"], explanation: "Confirmed mass encryption and removal of recovery copies support urgent ransomware response. Network isolation limits spread but may not stop encryption already running locally; coordinate endpoint containment and evidence preservation. The upload's size alone does not prove exfiltrated content. These are normalised sources, not invented raw event fields.", wrongFeedback: {0:"A service display name is attacker-controllable and cannot override the evidence of active encryption.", 2:"cipher /w clears free space; it is not an antivirus scan. Context is essential for interpreting legitimate tools.", 3:"The upload merits investigation, but without content or corroboration its exact data is unknown."} },
  p026: { objective: "3.4", ch: "3", scenario: "After emergency responders confirm personnel are safe, the recovery coordinator follows this plan for a damaged data centre: assess service impact, authorise disaster recovery, restore to the prepared recovery site, validate, switch users, then review the event. Order the tasks for this stated plan.", explanation: "Life safety and emergency procedures take priority. This exercise then follows the supplied recovery dependencies. Testing before the planned user cutover reduces the risk of restoring corrupt or unsafe service; actual failover procedures vary with architecture and urgency.", itemNotes: {a:"Restore the required data and systems at the prepared site after activation.", b:"Authorised activation mobilises the recovery plan and resources.", c:"Validate restored data, functionality and security before this planned cutover.", d:"Redirect users once the restored service passes the required acceptance checks.", e:"Assess the impact and recovery need after safety requirements are addressed.", f:"The retrospective improves the plan based on the recovery experience."} },
  p027: { difficulty: "medium", scenario: "A capture shows a very high rate of SYN packets to one HTTPS service from many apparent source addresses. Few handshakes complete, the server's half-open connection backlog grows, and legitimate connections fail. Source spoofing is suspected; the number of real sending devices is not yet known.", question: "Which attack and control best address the observed half-open state exhaustion?", choices: ["ARP poisoning; Dynamic ARP Inspection", "SYN flood; SYN-cookie protection with layered traffic controls", "DNS amplification; restrict recursive DNS", "TLS downgrade; HSTS"], explanation: "The evidence supports a SYN flood exhausting handshake state. SYN cookies can reduce state allocation until a peer completes the handshake. They do not solve every bandwidth or CPU exhaustion problem. Many apparent source IPs alone do not prove a distributed botnet when addresses may be spoofed.", wrongFeedback: {0:"ARP cache manipulation does not explain the SYN backlog growth.", 2:"The traffic is TCP SYN, not amplified UDP DNS replies.", 3:"HSTS concerns HTTPS transport policy; it does not manage half-open TCP state."} },
  p028: { objective: "4.6", scenario: "A password-based service is adopting a policy favouring long passwords, screening common or compromised values, rate limiting and MFA, without arbitrary periodic resets. Select the proposal matching those requirements.", options: ["Short passwords with frequent scheduled resets", "Complexity rules only, with no compromised-password screening", "Long passwords, compromised-password screening, rate limiting and MFA; reset when needed for compromise or recovery", "No password length or guessing controls because MFA is enabled"], explanation: "C meets the stated requirements. Current NIST guidance distinguishes single-factor from MFA password minimums and discourages arbitrary composition rules and periodic resets. A five-attempt threshold is not a universal mandate. Long passwords still need secure storage and controls against common guesses.", wrongFeedback: {0:"Frequent resets do not compensate for weak short passwords and conflict with the stated policy.", 1:"Composition alone does not screen widely known or compromised values and omits other required controls.", 3:"MFA does not justify removing all safeguards from a password factor that remains in use."} },
  p029: { scenario: "Complete these risk-analysis terms. Interpret the values as estimates and use a consistent period for occurrence rates and cost comparisons.", explanation: "SLE estimates single-event loss; ALE multiplies it by annual frequency. ARO is an expected rate, not a regular schedule. Qualitative ratings use categories and judgement, whereas quantitative analysis estimates numerical quantities; both involve assumptions.", blankNotes: {a:"Asset value times the loss fraction gives SLE, the estimated single-event loss.", b:"SLE times the expected annual frequency gives ALE.", c:"Occurrence describes event frequency in ARO.", d:"Exposure factor is the fraction of asset value lost in one event.", e:"High/medium/low categories are qualitative ratings rather than monetary loss estimates."} },
  p030: { difficulty: "medium", choices: ["Step 1", "Step 2", "Step 3", "Step 4"], explanation: "C lacks a documented handover, leaving custody continuity unsupported. Record who handled the evidence, when and why, with the acknowledgements required by the procedure. Digital systems may document transfers electronically; absence of a handwritten signature alone is not a universal admissibility rule.", wrongFeedback: {0:"The record describes scene documentation and identified collection, not the unrecorded transfer.", 1:"A documented image and modern integrity hash support preservation; MD5 is not a required alternative.", 3:"Working from a verified copy normally protects the original. Some live collection requires interacting with the source, so 'never touch the original' is not an absolute rule."} },
  p031: { targets: [{id:"1",label:"Health information handled by covered US healthcare entities and relevant associates"},{id:"2",label:"Payment-card account data security requirements"},{id:"3",label:"Personal-data processing within the regulation's EU territorial scope"},{id:"4",label:"Financial-reporting controls for covered public companies"},{id:"5",label:"Education-record rights at covered US educational institutions"}], explanation: "These are high-level scope examples, not interchangeable legal regimes. PCI DSS is an industry standard; the others listed are laws or regulations. Applicability, duties, exceptions and notification rules must be checked separately; not all have the same breach-notification obligation.", itemNotes: {a:"HIPAA applies through covered entities and business-associate relationships, not every piece of health information anywhere.", b:"PCI DSS addresses payment-card account data and relevant environments, not all financial reporting.", c:"GDPR scope depends on establishment and specified targeting or monitoring criteria, not citizenship alone.", d:"SOX addresses corporate accountability and financial-reporting controls, not general health or education records.", e:"FERPA applies to qualifying educational agencies and institutions, including conditions linked to US Department of Education funding."} },
  p032: { difficulty: "medium", answer: "Test 1: search?q=hello\nObserved DOM: <p>Results for: hello</p>\n\nTest 2: search?q=<b>hello</b>\nObserved: supplied text renders as bold markup.\n\nTest 3: search?q=<script>alert('XSS')</script>\nObserved: the injected script executes in this response's page context.\nNo persistence of the search term is found in this test.", choices: ["SQL injection; parameterise database statements", "Reflected XSS; encode untrusted output for its insertion context", "CSRF; add a request anti-forgery token", "Stored XSS; remove persisted malicious content"], explanation: "The supplied search term executes in the immediate response, supporting reflected XSS. Use context-appropriate output encoding or safe rendering APIs. HTML encoding is not universally sufficient inside JavaScript or URLs. CSP adds defence in depth; HttpOnly limits cookie reads but does not make an XSS-compromised session safe.", wrongFeedback: {0:"The observed execution occurs in the browser, not the database query parser.", 2:"CSRF concerns unauthorised requests using a victim's session, not this demonstrated script injection.", 3:"The test explicitly finds immediate reflection without persistence; stored XSS requires retained content but not necessarily a database or delivery to every user."} },
  p033: { difficulty: "medium", scenario: "Order this team's CSR-based certificate issuance workflow. The private key is generated in approved protected storage and remains under authorised custody. Deployment references that protected key, which may be in an HSM rather than a web-server file.", items: [{id:"a",label:"Deploy the certificate chain with access to the protected corresponding key"},{id:"b",label:"Generate the key pair in approved protected storage"},{id:"c",label:"Monitor validity and renew according to the service lifecycle"},{id:"d",label:"Submit the CSR to the chosen CA"},{id:"e",label:"Create and sign the CSR with the public key and requested names"},{id:"f",label:"Complete CA validation and receive the issued certificate"}], explanation: "Generate a protected key, create and submit its CSR, complete required validation, deploy and monitor. The CSR contains public information and proof of possession, not the private key. Keys can reside in HSMs or move through controlled backup/migration processes; 'never leaves the server' is not a universal PKI rule.", itemNotes: {a:"Deploy after issuance, with the appropriate chain and protected key integration.", b:"A corresponding key pair must exist before the CSR is signed.", c:"Monitoring and renewal maintain the deployed credential over time; lifetimes vary.", d:"Submit the CSR, not an unprotected private key, to the issuer.", e:"The CSR includes the public key and requested identity information and is signed with the matching private key.", f:"The CA completes its required validation before issuing the certificate."} },
  p034: { scenario: "An account records London and Singapore sign-ins five minutes apart, both in UTC. No expected VPN is identified. The second session uses a new device and attempts an unusual sensitive export. The approved response plan permits temporary access restriction for this combined high-risk pattern.", choices: ["Ignore because MFA was enabled", "Temporarily restrict the account, revoke sessions and verify through a trusted independent channel", "Wait a day without investigating", "Permanently block all traffic from Singapore"], explanation: "The combined anomalies support proportionate containment and verification under the supplied plan. Geolocation and impossible-travel alerts are imperfect and do not alone prove takeover. MFA can be bypassed or abused, so investigate session actions, device evidence and legitimate-user confirmation.", wrongFeedback: {0:"MFA reduces risk but does not establish that every successful session is legitimate.", 2:"The sensitive export and combined anomalies justify timely action under the stated authority.", 3:"A country-wide permanent block is broader than the targeted account response and does not establish the cause."} },
  p035: { explanation: "A forward proxy mediates client requests; a jump server provides a monitored administrative entry path; a screened subnet separates exposed services. Stateful filtering uses connection context. In this exercise the IDS is passive and the IPS inline. A bastion is a hardened exposed host and need not always be a jump server.", blankNotes: {a:"A forward proxy makes or forwards requests on clients' behalf and can apply policy.", b:"A jump server provides the specified controlled administration path into a protected zone.", c:"A DMZ is a screened network zone for services with different exposure requirements.", d:"Stateful inspection uses tracked connection state rather than only independent packet fields.", e:"The passive IDS alerts; inline prevention is the IPS role described."} },
};

// These imports present three unrelated placeholder answers rather than genuine
// competing solutions. Preserve source/history, but do not serve them to learners.
export const RETIRED_PBQ_REVIEW = Object.fromEntries([
  "p201", "p202", "p203", "p204", "p205", "p206", "p207", "p208", "p209", "p210",
  "p212", "p213", "p214", "p215", "p216", "p217", "p218", "p219", "p220", "p221", "p222",
].map(id => [id, "Unusable imported assessment: unrelated placeholder distractors reveal the only substantive answer. Retired rather than counted as meaningful practice."]));

Object.assign(PBQ_REVIEW, PUBLISHED_PBQ_REVIEW);
for (const [id, patch] of Object.entries(SECOND_PASS_PBQ_REVIEW)) PBQ_REVIEW[id] = {...PBQ_REVIEW[id], ...patch};
for (const [id, patch] of Object.entries(CONCISE_PBQ_REVIEW)) PBQ_REVIEW[id] = {...PBQ_REVIEW[id], ...patch};
export const isPbqEditoriallyActive = question => !RETIRED_PBQ_REVIEW[question.id];

export function applyPbqEditorialReview(question) {
  const review = PBQ_REVIEW[question.id];
  if (!review) return question;
  const { itemNotes, blankNotes, ...patch } = review;
  const next = { ...question, ...patch, editorialReviewed: true };
  if (itemNotes) next.items = next.items.map(item => ({ ...item, explanation: itemNotes[item.id] || item.explanation }));
  if (blankNotes) next.blanks = next.blanks.map(blank => ({ ...blank, explanation: blankNotes[blank.id] || blank.explanation }));
  if (question.id === "p021") next.question = "Which pairing correctly classifies this passive IDS?";
  if (question.id === "p011") next.blanks = next.blanks.map(blank => blank.id === "d" ? {...blank, acceptedAnswers:["Fraction", "Proportion"]} : blank);
  if (question.id === "p035") next.blanks = next.blanks.map(blank => blank.id === "b" ? {...blank, sentence:"A ___ provides a monitored administrative entry path into a protected network."} : blank);
  // Reviewed matching activities use a bounded, explained bank. Random generic
  // distractors added by UI normalisation are not part of the editorial content.
  if (["DRAG & DROP", "FILL BLANK", "SELECT & FILL"].includes(next.type)) {
    const originalType = next.type;
    if (originalType === "DRAG & DROP") {
      const labels = Object.fromEntries(next.targets.map(target => [target.id, target.label]));
      next.blanks = next.items.map(item => ({id:item.id, sentence:`${item.label} → ___`, answer:labels[next.correctMapping[item.id]], explanation:item.explanation}));
    }
    next.type = "SELECT & FILL";
    next.legacySelectionType = originalType;
    next.selectionOptions = [...new Set(next.blanks.map(blank => blank.answer))];
    next.selectionFeedback = Object.fromEntries(next.selectionOptions.map(option => [option, next.blanks.filter(blank => blank.answer === option).map(blank => blank.explanation).join(" ")]));
  }
  const choices = next.choices || next.options;
  if (choices) {
    next.options = next.choices = choices;
    next.optionFeedback = Object.fromEntries(choices.map((_, index) => [index, index === next.correct ? next.explanation : next.wrongFeedback?.[index]]));
  }
  return next;
}
